"""RegistryClient — Agent Card 注册与发现。

注册：将本员工 Agent Card 上报 CHIIP 后端（复用 heartbeat 通道语义，
后端暂无对应端点时静默降级为仅本地保存）。
发现：优先查询后端 agents 列表接口；不可用时回退扫描本地
{RUNTIME_HOME}/a2a/cards/ 缓存目录中的其他员工 Card。
"""
import json
import logging
import urllib.request
from pathlib import Path

logger = logging.getLogger("agent.a2a")


class RegistryClient:
    """向 CHIIP 后端注册本员工、发现其他员工。"""

    def __init__(self, config):
        self.config = config
        self.peer_dir = Path(config.a2a_dir) / 'cards'
        self.peer_dir.mkdir(parents=True, exist_ok=True)

    # ─────────────────────────────────────────
    # 注册
    # ─────────────────────────────────────────
    def register(self, card):
        """上报本员工 Agent Card。返回 True 表示后端确认收到。"""
        if not self.config.backend_url:
            logger.info('未配置 CHIIP_BACKEND_URL，Agent Card 仅本地保存')
            return False
        url = '%s/api/v1/agents/%s/register' % (
            self.config.backend_url, self.config.agent_id)
        req = urllib.request.Request(
            url,
            data=json.dumps(card, ensure_ascii=False).encode('utf-8'),
            headers={'Content-Type': 'application/json'},
            method='POST')
        if self.config.backend_token:
            req.add_header('Authorization',
                           'Token %s' % self.config.backend_token)
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status < 400:
                    logger.info('Agent Card 已注册到后端')
                    return True
        except Exception as e:  # noqa: BLE001 — 注册失败不影响运行
            logger.debug('Agent Card 注册失败（后端可能暂无该端点）: %s', e)
        return False

    # ─────────────────────────────────────────
    # 发现
    # ─────────────────────────────────────────
    def _discover_remote(self):
        url = '%s/api/v1/agents' % self.config.backend_url
        req = urllib.request.Request(url)
        if self.config.backend_token:
            req.add_header('Authorization',
                           'Token %s' % self.config.backend_token)
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read().decode('utf-8'))
        # 后端返回可能是列表或 {'results': [...]}
        items = data if isinstance(data, list) else data.get('results', [])
        cards = []
        for item in items:
            if not isinstance(item, dict):
                continue
            if item.get('agent_id') == self.config.agent_id:
                continue
            cards.append(item)
        return cards

    def _discover_local(self):
        cards = []
        for f in sorted(self.peer_dir.glob('*.json')):
            try:
                card = json.loads(f.read_text(encoding='utf-8'))
                if card.get('agent_id') != self.config.agent_id:
                    cards.append(card)
            except (ValueError, OSError):
                continue
        return cards

    def discover(self):
        """发现其他员工 Agent Card 列表（远程优先，本地缓存兜底）。"""
        if self.config.backend_url:
            try:
                return self._discover_remote()
            except Exception as e:  # noqa: BLE001
                logger.debug('后端发现失败，回退本地缓存: %s', e)
        return self._discover_local()

    # ─────────────────────────────────────────
    # 本地缓存
    # ─────────────────────────────────────────
    def cache_peer(self, card):
        """缓存一份其他员工的 Agent Card 到本地。"""
        agent_id = card.get('agent_id')
        if not agent_id:
            return
        try:
            (self.peer_dir / ('%s.json' % agent_id)).write_text(
                json.dumps(card, ensure_ascii=False, indent=2),
                encoding='utf-8')
        except OSError:
            pass
